THEMES = ['confidence', 'work', 'future', 'calm', 'love']
for theme in THEMES:
    if len(DATA[theme]) != 100:
        raise SystemExit(f'{theme}: expected 100, got {len(DATA[theme])}')

items = [(theme, text.strip()) for theme in THEMES for text in DATA[theme]]
texts = [text for _, text in items]

if len(items) != 500:
    raise SystemExit(f'Expected 500, got {len(items)}')
if len(set(texts)) != 500:
    raise SystemExit('Duplicate affirmations found')
if max(map(len, texts)) > 75:
    bad = [(len(t), t) for t in texts if len(t) > 75]
    raise SystemExit(f'Over 75 chars: {bad}')

negative = re.compile(r'(^|[\s—–,.;:!?])(не|без)(?=$|[\s—–,.;:!?])', re.I)
bad_negative = [t for t in texts if negative.search(t)]
if bad_negative:
    raise SystemExit(f'Negative constructions found: {bad_negative}')

rows = []
for theme, text in items:
    rows.append('      [' + json.dumps(theme, ensure_ascii=False) + ',' + json.dumps(text, ensure_ascii=False) + ']')
block = '    const AFFIRMATIONS = [\n' + ',\n'.join(rows) + '\n    ].map((x, i) => ({ id: `q${i+1}`, theme: x[0], text: x[1] }));'

pattern = r"    const AFFIRMATIONS = \[.*?\n    \]\.map\(\(x, i\) => \(\{ id: `[^`]+`, theme: x\[0\], text: x\[1\] \}\)\);"
src, n = re.subn(pattern, lambda _: block, src, count=1, flags=re.S)
if n != 1:
    raise SystemExit(f'Could not replace AFFIRMATIONS block: {n}')

src = src.replace("future: { label: 'Будущее'", "future: { label: 'Жизнь'")
for key in ['affirm_full_diary_saved_v1', 'affirm_mne_vygodno_saved', 'affirm_curated500_saved_v1']:
    src = src.replace(key, 'affirm_curated500_saved_v2')

p.write_text(src, encoding='utf-8')
print(f'Installed {len(items)} curated affirmations; max length {max(map(len, texts))}')
